import {Button, Flash, Spinner} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import {useEffect, useRef, useState} from 'react'
import type {SafeHTMLString} from '@github-ui/safe-html'
import {VerifiedHTMLDiv} from '@github-ui/safe-html/VerifiedHTML'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import type {SaveResponse} from '@github-ui/code-view-types'
import type {User} from './types'
import styles from './RemoveMemberDialog.module.css'

type RemoveMemberDialogProps = {
  teamName: string
  member: User
  removeMemberPath: string
  onMemberRemove: () => void
  onDismiss: () => void
}

export function RemoveMemberDialog({
  teamName,
  member,
  removeMemberPath,
  onMemberRemove,
  onDismiss,
}: RemoveMemberDialogProps) {
  const [showLoadingSpinner, setShowLoadingSpinner] = useState<boolean>(false)
  /* eslint-disable-next-line @github-ui/github-monorepo/no-cast-as-safe-html-string -- Safe empty string initialization. SECURITY XSS risk: Do not modify with user input. Verified: only replaced with server-sanitized HTML. */
  const [flash, setFlash] = useState<SafeHTMLString>('' as SafeHTMLString)

  const flashRef = useRef<HTMLDivElement | null>(null)
  useEffect(() => {
    flashRef.current?.focus()
  }, [flash, flashRef])

  const handleDismiss = () => {
    /* eslint-disable-next-line @github-ui/github-monorepo/no-cast-as-safe-html-string -- Safe empty string reset. SECURITY XSS risk: Do not modify with user input. */
    setFlash('' as SafeHTMLString)
    onDismiss()
  }

  const removeMemberFromTeam = async () => {
    setShowLoadingSpinner(true)
    /* eslint-disable-next-line @github-ui/github-monorepo/no-cast-as-safe-html-string -- Safe empty string reset. SECURITY XSS risk: Do not modify with user input. */
    setFlash('' as SafeHTMLString)
    try {
      const result = await verifiedFetchJSON(`${removeMemberPath}/${member.login}`, {
        method: 'DELETE',
        headers: {Accept: 'application/json'},
      })

      const json: SaveResponse = await result.json()
      if (json.data.error) {
        /* eslint-disable-next-line @github-ui/github-monorepo/no-cast-as-safe-html-string -- TODO: [SECURITY] Potential XSS risk. Pre-existing infraction - DO NOT COPY. Must be fixed. */
        setFlash(json.data.error as SafeHTMLString)
      } else if (json.data) {
        onMemberRemove()
      } else {
        // error uses a different format
        /* eslint-disable-next-line @github-ui/github-monorepo/no-cast-as-safe-html-string -- Static string literal is safe */
        setFlash('An error occurred.' as SafeHTMLString)
      }
    } catch {
      // Internal server error or other server errors
      /* eslint-disable-next-line @github-ui/github-monorepo/no-cast-as-safe-html-string -- Static string literal is safe */
      setFlash('An error occurred.' as SafeHTMLString)
    }
    setShowLoadingSpinner(false)
  }

  return (
    <Dialog
      onClose={handleDismiss}
      title={`Removing member from ${teamName}`}
      renderFooter={() => {
        return (
          <Dialog.Footer>
            <Button type="button" onClick={handleDismiss}>
              Cancel
            </Button>
            <Button type="button" variant="danger" disabled={showLoadingSpinner} onClick={removeMemberFromTeam}>
              {showLoadingSpinner ? <Spinner size="small" className={styles.spinner} /> : 'Remove'}
            </Button>
          </Dialog.Footer>
        )
      }}
    >
      {flash && (
        <Flash data-testid="flash-error" tabIndex={0} ref={flashRef} variant="danger" className={styles.flashError}>
          <VerifiedHTMLDiv html={flash} />
        </Flash>
      )}
      {`Are you sure that you want to remove '${member.name || member.login}' from the enterprise team?`}
    </Dialog>
  )
}
